using System;using System.Drawing;using System.Drawing.Imaging;using System.Diagnostics;using System.IO;using System.Linq;using IslandIntegrated;
class CornerGlassTests {
 static int checks;static void Check(bool ok,string name){if(!ok)throw new Exception(name);checks++;}
 static double Linear(byte b){double n=b/255.0;return n<=.04045?n/12.92:Math.Pow((n+.055)/1.055,2.4);}
 static double Lum(Color c){return .2126*Linear(c.R)+.7152*Linear(c.G)+.0722*Linear(c.B);}
 static Color Blend(Color a,Color b,double alpha){return Color.FromArgb((int)(a.R*alpha+b.R*(1-alpha)),(int)(a.G*alpha+b.G*(1-alpha)),(int)(a.B*alpha+b.B*(1-alpha)));}
 static double Ratio(Color a,Color b){return (Math.Max(Lum(a),Lum(b))+.05)/(Math.Min(Lum(a),Lum(b))+.05);}
 static Bitmap Surface(int width,int height,bool backing,double phase){var bmp=new Bitmap(width,height,PixelFormat.Format32bppArgb);using(var g=Graphics.FromImage(bmp)){g.Clear(Color.Transparent);GlassSurface.Paint(g,new RectangleF(0,0,width-1,height-1),24,backing);GlassSurface.PaintShimmer(g,new RectangleF(0,0,width-1,height-1),24,phase);}return bmp;}
 static int Main(){try{
  var review=Path.GetFullPath(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"..","..","..","corner-glass-review"));Directory.CreateDirectory(review);
  var areas=new[]{new Rectangle(0,0,2560,1392),new Rectangle(-1920,-200,1920,1040),new Rectangle(2560,0,1280,720),new Rectangle(0,-1080,1920,1040)};
  foreach(var area in areas){var body=CornerLayout.Body(area,74,16,17);var detail=CornerLayout.Body(area,424,16,17);var column=CornerLayout.Column(area,16,17);
   Check(area.Contains(body)&&body.Top==area.Top+16,"Status fixed to target top");Check(body.Left==column.Left&&body.Width==column.Width,"Common component horizontal edges");Check(body.Left==detail.Left&&body.Top==detail.Top,"Detail does not center or move anchor");Check(column.Top==body.Bottom+12&&area.Contains(column),"Independent column geometry below compact anchor");Check(detail.Height!=body.Height&&CornerLayout.Column(area,16,17)==column,"Detail height cannot move widget column");}
  foreach(int dpi in new[]{96,144,192}){int shadow=16*dpi/96,scroll=17*dpi/96;var area=new Rectangle(-2000,0,2000,1400);var body=CornerLayout.Body(area,74,shadow,scroll);Check(area.Contains(body)&&body.Top==shadow,"Geometry stays bounded with scaled input margins (not native DPI proof)");}
  var clock=new HighlightClock();int frames=0;for(int ms=0;ms<60000;ms++)if(clock.Tick(ms,true,false,false))frames++;Check(frames<=600&&frames>=590,"Highlight cap at ten per second");int hidden=0;for(int ms=60000;ms<120000;ms++)if(clock.Tick(ms,false,false,false))hidden++;Check(hidden==0,"Hidden animation stopped");int reduced=0;for(int ms=120000;ms<180000;ms++)if(clock.Tick(ms,true,true,false))reduced++;Check(reduced==0,"Reduced motion stopped");Check(!clock.Tick(180000,true,false,true),"Busy editing/dragging stops animation");Check(clock.Tick(180001,true,false,false)&&clock.Phase==0,"Resume restarts sweep without fast-forward jump");
  double maxDirty=0;for(int i=0;i<=100;i++){var dirty=GlassSurface.ShimmerBounds(new Rectangle(0,0,344,380),i/100.0);if(dirty.Width>0)maxDirty=Math.Max(maxDirty,dirty.Width/344.0);}Check(maxDirty<.35,"Only a narrow card region is invalidated");
  double minContrast=100;using(var material=Surface(344,164,true,.5)){foreach(var desktop in new[]{Color.Black,Color.White,Color.FromArgb(0,120,215),Color.FromArgb(220,220,220)}){var background=Blend(material.GetPixel(80,70),desktop,.84);var text=Blend(Color.FromArgb(240,244,250),desktop,.84);minContrast=Math.Min(minContrast,Ratio(text,background));}}Check(minContrast>=4.5,"Body text contrast over test extremes");
  using(var status=Surface(344,74,false,.5)){Check(status.GetPixel(172,37).A<255,"Status retains real per-pixel alpha");}
  var times=new double[200];using(var cache=new StatusFrameCache(16))using(var source=new Bitmap(376,106)){using(var g=Graphics.FromImage(source))g.Clear(Color.FromArgb(200,34,52,72));cache.Update(source);Check(cache.MatchesSize(source.Size)&&!cache.MatchesSize(new Size(376,456)),"Do not reuse cached pixels for wrong geometry");bool sizes=true;for(int i=0;i<times.Length;i++){var watch=Stopwatch.StartNew();using(var frame=cache.Compose(i/200.0,true)){times[i]=watch.Elapsed.TotalMilliseconds;sizes=sizes&&frame.Size==source.Size;}}Check(sizes,"Cached highlight preserves frame size");Check(cache.BaseUpdates==1&&cache.Compositions==200,"Highlight composition does not rerun base raster");cache.Dispose();Check(cache.Compose(.2,true)==null,"Disposed cache cannot submit more frames");}
  Array.Sort(times);double p95=times[(int)(times.Length*.95)-1];
  using(var cache=new StatusFrameCache(16))using(var source=new Bitmap(376,106)){using(var g=Graphics.FromImage(source)){g.Clear(Color.Transparent);GlassSurface.Paint(g,new RectangleF(16,16,344,74),37,false);}cache.Update(source);using(var frame=cache.Compose(.18,true))Check(frame.GetPixel(17,17).A==0,"Highlight cannot introduce square pixels outside capsule corners");}
  var live=Layout.Default();live.ReduceMotion=true;live.SolidCards=true;var edit=new LayoutEditSession(live);edit.Draft.ReduceMotion=false;edit.Draft.SolidCards=false;edit.Cancel();Check(live.ReduceMotion&&live.SolidCards,"Cancel preserves accessibility preferences");
  string fixture=Path.Combine(review,"prefs-fixture-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(fixture);string file=Path.Combine(fixture,"layout.xml");LayoutStore.Save(file,live);var loaded=LayoutStore.Load(file);Check(loaded.ReduceMotion&&loaded.SolidCards,"Preferences round trip");var save=new LayoutEditSession(live);save.Draft.ReduceMotion=false;save.Save(file);Check(!live.ReduceMotion&&LayoutStore.Load(file).SolidCards,"Explicit save copies new preferences");
  using(var canvas=new Bitmap(760,450))using(var g=Graphics.FromImage(canvas)){
   g.Clear(Color.FromArgb(26,33,44));using(var b=new SolidBrush(Color.FromArgb(231,240,248)))g.DrawString("Renderer study: owned background, no desktop capture / no blur",SystemFonts.MessageBoxFont,b,16,12);
   for(int i=0;i<3;i++)using(var card=Surface(220,320,true,.25+i*.25)){var rect=new Rectangle(16+i*248,60,220,320);using(var attrs=new ImageAttributes()){var matrix=new ColorMatrix();matrix.Matrix33=.84f;attrs.SetColorMatrix(matrix);g.DrawImage(card,rect,0,0,220,320,GraphicsUnit.Pixel,attrs);}using(var b=new SolidBrush(Color.FromArgb(239,245,251)))g.DrawString("Cached glass material\nSubtle moving highlight\nOpaque text remains legible",SystemFonts.MessageBoxFont,b,rect.X+14,rect.Y+32);}
   canvas.Save(Path.Combine(review,"material-study.png"),ImageFormat.Png);
  }
  string result="{\"checks\":"+checks+",\"maxFps\":10,\"simulatedVisibleFrames60s\":"+frames+",\"hiddenFrames60s\":"+hidden+",\"reducedFrames60s\":"+reduced+",\"maxDirtyWidthFraction\":"+maxDirty.ToString(System.Globalization.CultureInfo.InvariantCulture)+",\"testContrastMinimum\":"+minContrast.ToString(System.Globalization.CultureInfo.InvariantCulture)+",\"cachedCompositionP95Ms\":"+p95.ToString(System.Globalization.CultureInfo.InvariantCulture)+",\"nativeTransferIncluded\":false,\"nativeDpiVerified\":false,\"guiStarted\":false}";File.WriteAllText(Path.Combine(review,"tests.json"),result);Console.WriteLine(result);return 0;
 }catch(Exception error){Console.Error.WriteLine(error);return 1;}}
}
